extends RefCounted
## Бег и рывок героя на плоскости (поведение по Wizard of Legend). Один вызов = один тик.
const Collision := preload("res://sim/collision.gd")


## input: {"move": Vector2 (длина ≤ 1), "dash": bool, "jump": bool — нажатия в этот тик}
static func step(st: RefCounted, input: Dictionary, bal: Dictionary) -> void:
	var rate := float(bal["sim"]["tick_rate"])
	var dt := 1.0 / rate
	var p: Dictionary = st.player
	var move: Vector2 = input.get("move", Vector2.ZERO)
	if move.length() > 1.0:
		move = move.normalized()
	if move.length() < float(bal["sim"]["move_deadzone"]):
		move = Vector2.ZERO

	_recharge(p, bal, rate)
	if input.get("dash", false):
		p["dash_buf"] = roundi(float(bal["dash"]["buffer"]) * rate)
	elif p["dash_buf"] > 0:
		p["dash_buf"] -= 1
	if p["dash_left"] == 0 and p["dash_buf"] > 0 and p["charges"] > 0:
		_start_dash(p, move, bal, rate)

	var delta: Vector2
	if p["dash_left"] > 0:
		var total := roundi(float(bal["dash"]["duration"]) * rate)
		var frac := (float(total - p["dash_left"]) + 0.5) / float(total)  # доля пройденного, середина тика
		var peak: float = 2.0 * float(bal["dash"]["distance"]) / float(bal["dash"]["duration"])
		p["vel"] = p["dash_dir"] * peak * (1.0 - frac)  # линейно до нуля: путь = distance
		p["dash_left"] -= 1
		delta = p["vel"] * dt
		if p["dash_left"] == 0:
			p["vel"] = Vector2.ZERO
	else:
		var speed := float(bal["player"]["run_speed"])
		var secs := float(bal["player"]["run_accel_time"] if move != Vector2.ZERO else bal["player"]["run_decel_time"])
		p["vel"] = (p["vel"] as Vector2).move_toward(move * speed, speed / maxf(secs * rate, 1.0))
		if move != Vector2.ZERO:
			p["facing"] = move.normalized()
		delta = p["vel"] * dt
	_jump(p, input.get("jump", false), bal, dt)
	p["pos"] = Collision.move(p["pos"], delta, float(bal["player"]["radius"]), st.level, bal)


static func _start_dash(p: Dictionary, move: Vector2, bal: Dictionary, rate: float) -> void:
	var dir: Vector2 = move.normalized() if move != Vector2.ZERO else p["facing"]
	p["dash_dir"] = dir
	p["facing"] = dir
	p["dash_left"] = roundi(float(bal["dash"]["duration"]) * rate)
	p["dash_buf"] = 0
	if p["charges"] == int(bal["dash"]["charges"]):
		p["recharge"] = roundi(float(bal["dash"]["cooldown"]) * rate)
	p["charges"] -= 1


static func _recharge(p: Dictionary, bal: Dictionary, rate: float) -> void:
	if p["charges"] >= int(bal["dash"]["charges"]):
		return
	p["recharge"] -= 1
	if p["recharge"] <= 0:
		p["charges"] += 1
		p["recharge"] = roundi(float(bal["dash"]["cooldown"]) * rate) if p["charges"] < int(bal["dash"]["charges"]) else 0


## Прыжок по вертикали: высота и длительность из balance.toml, g и v0 выводятся (h = v0²/2g, T = 2·v0/g).
## Во время рывка не стартует; управление в воздухе — обычное.
static func _jump(p: Dictionary, pressed: bool, bal: Dictionary, dt: float) -> void:
	var h := float(bal["jump"]["height"])
	var t := float(bal["jump"]["duration"])
	if p["z"] <= 0.0 and p["vz"] <= 0.0 and pressed and p["dash_left"] == 0:
		p["vz"] = 4.0 * h / t
	if p["z"] > 0.0 or p["vz"] > 0.0:
		var g := 8.0 * h / (t * t)
		p["z"] += p["vz"] * dt - 0.5 * g * dt * dt  # точное интегрирование при постоянной g
		p["vz"] -= g * dt
		if p["z"] <= 0.0:
			p["z"] = 0.0
			p["vz"] = 0.0
			p["landed"] = float(bal["jump"]["land_time"])
	elif p["landed"] > 0.0:
		p["landed"] = maxf(p["landed"] - dt, 0.0)

extends RefCounted
## Вход в симуляцию: создать мир, шагнуть тик, прогнать реплей. Данные грузятся из data/ (инвариант 6).
const TomlLite := preload("res://sim/toml_lite.gd")
const WorldState := preload("res://sim/world_state.gd")
const Movement := preload("res://sim/movement.gd")

const BALANCE_PATH := "res://data/balance.toml"

var bal: Dictionary
var state: RefCounted


static func load_json(path: String) -> Dictionary:
	var f := FileAccess.open(path, FileAccess.READ)
	if f == null:
		push_error("sim: нет файла " + path)
		return {}
	var parsed: Variant = JSON.parse_string(f.get_as_text())
	return parsed if parsed is Dictionary else {}


func _init(seed_value: int, level_path: String, balance: Dictionary = {}) -> void:
	bal = balance if not balance.is_empty() else TomlLite.load_file(BALANCE_PATH)
	state = WorldState.new(seed_value, load_json(level_path), bal)


func step(input: Dictionary) -> void:
	Movement.step(state, input, bal)
	state.tick += 1


## Реплей: {"seed", "level", "ticks", "inputs":[{"t", "mx"?, "my"?, "dash"?, "jump"?}]}.
## mx/my держатся до следующей записи; dash — импульс одного тика t. on_tick(sim) зовётся после каждого тика.
static func run_replay(rep: Dictionary, on_tick := Callable()) -> RefCounted:
	var s := new(int(rep["seed"]), str(rep["level"]))
	var inputs: Array = rep["inputs"]
	var i := 0
	var move := Vector2.ZERO
	for t in int(rep["ticks"]):
		var dash := false
		var jump := false
		while i < inputs.size() and int(inputs[i]["t"]) == t:
			var e: Dictionary = inputs[i]
			if e.has("mx") or e.has("my"):
				move = Vector2(float(e.get("mx", move.x)), float(e.get("my", move.y)))
			dash = dash or bool(e.get("dash", false))
			jump = jump or bool(e.get("jump", false))
			i += 1
		s.step({"move": move, "dash": dash, "jump": jump})
		if on_tick.is_valid():
			on_tick.call(s)
	return s

extends Node3D
## Сцена Мыса (техно-демка). Вид только читает sim: ввод -> sim.step в _physics_process, позиции -> узлы.
## Ось: плоскость sim (x, y) -> мир (x, высота, y); экран «вверх» = -y.
const Sim := preload("res://sim/sim.gd")
const Rng := preload("res://sim/rng.gd")
const LEVEL := "res://data/levels/cape.json"
const MODELS := "res://assets/models/"
const SEED := 1

var sim: RefCounted
var bal: Dictionary
var hero: Node3D
var cam: Camera3D
var focus := Vector3.ZERO
var prev_pos := Vector2.ZERO
var cur_pos := Vector2.ZERO
var prev_z := 0.0
var cur_z := 0.0
var anim_state := ""
var anim: Node  # view/hero_anim.gd, если есть
var crab: Node3D  # покачивается на месте (без ИИ)
var clock := 0.0
var auto_inputs: Array = []  # --autoplay <реплей>: ввод берётся из файла (запись демо), а не с клавиатуры
var auto_tick := 0
var auto_move := Vector2.ZERO


func _ready() -> void:
	sim = Sim.new(SEED, LEVEL)
	bal = sim.bal
	_build_environment()
	_build_ground()
	_build_props()
	_build_hero()
	_build_camera()
	cur_pos = sim.state.player["pos"]
	prev_pos = cur_pos
	focus = Vector3(cur_pos.x, 0.0, cur_pos.y)
	_place()
	var args := OS.get_cmdline_user_args()
	var ai := args.find("--autoplay")
	if ai >= 0 and ai + 1 < args.size():
		auto_inputs = Sim.load_json("res://" + args[ai + 1].trim_prefix("res://")).get("inputs", [])


func _physics_process(_dt: float) -> void:
	var inp := {
		"move": Input.get_vector("move_left", "move_right", "move_up", "move_down"),
		"dash": Input.is_action_just_pressed("dash"),
		"jump": Input.is_action_just_pressed("jump"),
	}
	if not auto_inputs.is_empty():
		inp = _auto_input()
	prev_pos = cur_pos
	prev_z = cur_z
	sim.step(inp)
	cur_pos = sim.state.player["pos"]
	cur_z = sim.state.player["z"]


func _process(dt: float) -> void:
	_place()
	_sway_crab(dt)
	var c: Dictionary = bal["camera"]
	var target := hero.position
	target.y = 0.0
	focus = focus.lerp(target, 1.0 - exp(-float(c["follow_rate"]) * dt))
	_aim_camera()
	_update_anim()


## Краб стоит и покачивается: крен и небольшой подъём по синусу (только вид, sim не трогает).
func _sway_crab(dt: float) -> void:
	if crab == null:
		return
	var a: Dictionary = bal["ambient"]
	clock += dt
	var s := sin(clock * TAU * float(a["crab_sway_hz"]))
	crab.rotation.z = deg_to_rad(float(a["crab_sway_deg"])) * s
	crab.position.y = float(a["crab_bob"]) * absf(s)


## Ввод из файла реплея (та же семантика, что у Sim.run_replay): mx/my держатся, dash/jump — импульс тика.
func _auto_input() -> Dictionary:
	var dash := false
	var jump := false
	for e in auto_inputs:
		if int(e["t"]) != auto_tick:
			continue
		if e.has("mx") or e.has("my"):
			auto_move = Vector2(float(e.get("mx", auto_move.x)), float(e.get("my", auto_move.y)))
		dash = dash or bool(e.get("dash", false))
		jump = jump or bool(e.get("jump", false))
	auto_tick += 1
	return {"move": auto_move, "dash": dash, "jump": jump}


## Для tools/screenshot.gd: поставить героя в точку (кадр с маяком и т. п.).
func teleport(x: float, y: float) -> void:
	sim.state.player["pos"] = Vector2(x, y)
	prev_pos = sim.state.player["pos"]
	cur_pos = prev_pos
	focus = Vector3(x, 0.0, y)
	_place()


## Состояние героя из sim -> имя клипа (idle / run / dash / jump_up / jump_down / land).
func hero_state() -> String:
	var p: Dictionary = sim.state.player
	if p["dash_left"] > 0:
		return "dash"
	if p["z"] > 0.0 or p["vz"] > 0.0:
		return "jump_up" if p["vz"] > 0.0 else "jump_down"
	if float(p["landed"]) > 0.0:
		return "land"
	if (p["vel"] as Vector2).length() > 0.5:
		return "run"
	return "idle"


## Для tools/screenshot.gd: поза клипа в момент t, без перетекания.
func pose(clip: String, t: float) -> void:
	if anim != null:
		anim.call("snap", clip, t)


func _update_anim() -> void:
	var s := hero_state()
	if s != anim_state:
		anim_state = s
		if anim != null:
			anim.call("play_state", s)


func _place() -> void:
	var f := Engine.get_physics_interpolation_fraction()
	var p := prev_pos.lerp(cur_pos, f)
	hero.position = Vector3(p.x, lerpf(prev_z, cur_z, f), p.y)
	var face: Vector2 = sim.state.player["facing"]
	hero.rotation.y = atan2(face.x, face.y)


func _aim_camera() -> void:
	var c: Dictionary = bal["camera"]
	var pitch := deg_to_rad(float(c["pitch_deg"]))
	var dir := Vector3(0.0, sin(pitch), cos(pitch))
	cam.position = focus + dir * float(c["distance"])
	cam.look_at(focus, Vector3.UP)


func _build_camera() -> void:
	var c: Dictionary = bal["camera"]
	cam = Camera3D.new()
	cam.fov = float(c["fov_deg"])
	cam.near = float(c["near"])
	cam.far = float(c["far"])
	cam.current = true
	add_child(cam)
	_aim_camera()


func _build_environment() -> void:
	var l: Dictionary = bal["light"]
	var env := Environment.new()
	env.background_mode = Environment.BG_COLOR
	env.background_color = Color(str(l["sky_color"]))
	env.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	env.ambient_light_color = Color(str(l["ambient_color"]))
	env.ambient_light_energy = float(l["ambient_energy"])
	var we := WorldEnvironment.new()
	we.environment = env
	add_child(we)
	var sun := DirectionalLight3D.new()
	sun.light_color = Color(str(l["sun_color"]))
	sun.light_energy = float(l["sun_energy"])
	sun.rotation_degrees = Vector3(-float(l["sun_pitch_deg"]), float(l["sun_yaw_deg"]), 0.0)
	sun.shadow_enabled = true
	sun.directional_shadow_max_distance = float(l["shadow_distance"])
	add_child(sun)


func _mat(color: Color) -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.albedo_color = color
	m.roughness = 1.0
	m.texture_filter = BaseMaterial3D.TEXTURE_FILTER_NEAREST
	return m


func _box(size: Vector3, pos: Vector3, mat: Material, yaw := 0.0) -> MeshInstance3D:
	var mi := MeshInstance3D.new()
	var bm := BoxMesh.new()
	bm.size = size
	mi.mesh = bm
	mi.material_override = mat
	mi.position = pos
	mi.rotation.y = yaw
	add_child(mi)
	return mi


func _build_ground() -> void:
	var g: Dictionary = bal["ground"]
	var b: Dictionary = sim.state.level["bounds"]
	var lo := Vector2(b["min"][0], b["min"][1])
	var hi := Vector2(b["max"][0], b["max"][1])
	var depth := float(g["cliff_depth"])
	var size := hi - lo + Vector2(depth, depth) * 2.0
	var mid := (lo + hi) * 0.5
	var sand := _mat(Color(str(g["sand_color"])))
	_box(Vector3(size.x, 0.5, size.y), Vector3(mid.x, -0.25, mid.y), sand)
	var rng := Rng.new(int(g["view_seed"]))
	var slab := _mat(Color(str(g["slab_color"])))
	var th := float(g["slab_thickness"])
	for _i in int(g["slab_count"]):
		var w := lerpf(float(g["slab_min"]), float(g["slab_max"]), rng.next_float())
		var d := lerpf(float(g["slab_min"]), float(g["slab_max"]), rng.next_float())
		var x := lerpf(lo.x, hi.x, rng.next_float())
		var y := lerpf(lo.y, hi.y, rng.next_float())
		_box(Vector3(w, th, d), Vector3(x, th * 0.5, y), slab, rng.next_float() * TAU)
	var rock := _mat(Color(str(g["rock_color"])))
	for _i in int(g["rock_count"]):
		# валуны по периметру, в полосе cliff_depth за границей арены
		var side := rng.range_int(0, 3)
		var t := rng.next_float()
		var o := lerpf(0.5, depth, rng.next_float())
		var p := Vector2.ZERO
		match side:
			0: p = Vector2(lerpf(lo.x, hi.x, t), lo.y - o)
			1: p = Vector2(lerpf(lo.x, hi.x, t), hi.y + o)
			2: p = Vector2(lo.x - o, lerpf(lo.y, hi.y, t))
			_: p = Vector2(hi.x + o, lerpf(lo.y, hi.y, t))
		var w := lerpf(float(g["rock_min"]), float(g["rock_max"]), rng.next_float())
		var h := lerpf(float(g["rock_height_min"]), float(g["rock_height_max"]), rng.next_float())
		if side == 0:
			h *= 1.6  # северный обрыв выше остальных
		_box(Vector3(w, h, w * 0.8), Vector3(p.x, h * 0.5 - 0.1, p.y), rock, rng.next_float() * TAU)


func _build_props() -> void:
	var l: Dictionary = bal["light"]
	for prop in sim.state.level["props"]:
		var scene := load(MODELS + str(prop["model"]) + ".glb") as PackedScene
		var node := scene.instantiate() as Node3D
		node.position = Vector3(float(prop["x"]), 0.0, float(prop["y"]))
		node.rotation_degrees.y = float(prop.get("yaw", 0.0))
		add_child(node)
		if str(prop["model"]) == "crab_armored":
			crab = node
		if str(prop["model"]) == "lighthouse":
			_setup_lighthouse(node, str(prop.get("state", "lit")) == "lit", l)


## В lighthouse.glb два состояния рядом по X (off = -8, lit = +8): оставляем одно и ставим башню в начало.
func _setup_lighthouse(node: Node3D, lit: bool, l: Dictionary) -> void:
	for child in node.get_children():
		var is_lit := child.name.begins_with("LH_lit")
		child.visible = (is_lit == lit)
		if child.visible:
			(child as Node3D).position.x = 0.0
	if lit:
		var lamp := OmniLight3D.new()
		lamp.light_color = Color(str(l["lamp_color"]))
		lamp.light_energy = float(l["lamp_energy"])
		lamp.omni_range = float(l["lamp_range"])
		lamp.shadow_enabled = true
		lamp.position = Vector3(0.0, float(l["lamp_height"]), 0.0)
		node.add_child(lamp)


func _build_hero() -> void:
	var scene := load(MODELS + "hero_caster.glb") as PackedScene
	hero = Node3D.new()
	hero.name = "Hero"
	add_child(hero)
	hero.add_child(scene.instantiate())
	var script := load("res://view/hero_anim.gd") if ResourceLoader.exists("res://view/hero_anim.gd") else null
	if script != null:
		anim = script.new()
		hero.add_child(anim)

extends Node
## Анимация героя: конечный автомат клипов из data/anim/hero.json на скелете MPFB2 (кости mixamorig_*).
## Состояние даёт вид (cape.gd) из sim; здесь только позы и перетекание между ними.
const DATA := "res://data/anim/hero.json"

var skel: Skeleton3D
var names: PackedStringArray = []
var clips: Dictionary
var base: Dictionary
var prefix := ""
var state := "idle"
var time := 0.0
var frozen := false
var cur := {}      # кость -> Vector3 (радианы), текущая поза после перетекания
var cur_pos := Vector3.ZERO
var cur_g: Array[Basis] = []


func _ready() -> void:
	var d: Dictionary = JSON.parse_string(FileAccess.get_file_as_string(DATA))
	clips = d["clips"]
	base = d["base"]
	prefix = str(d["bone_prefix"])
	skel = get_parent().find_children("*", "Skeleton3D", true, false)[0] as Skeleton3D
	for m in d.get("hide_meshes", []):
		var mi := skel.get_node_or_null(str(m)) as Node3D
		if mi != null:
			mi.visible = false
	for i in skel.get_bone_count():
		names.append(skel.get_bone_name(i).trim_prefix(prefix))
		cur_g.append(Basis.IDENTITY)
	snap("idle", 0.0)


func play_state(s: String) -> void:
	if clips.has(s) and not frozen:
		state = s
		if s == "dash" or s == "land" or s == "jump_up":
			time = 0.0


## Мгновенная поза (для снимков): без перетекания, держится.
func snap(s: String, t: float) -> void:
	state = s
	time = t
	frozen = true
	var tgt := _target(s, t)
	cur = tgt["bones"]
	cur_pos = tgt["pos"]
	_apply()


func _process(dt: float) -> void:
	if frozen:
		return
	time += dt
	var clip: Dictionary = clips[state]
	var tgt := _target(state, time)
	var k := 1.0 - exp(-dt / maxf(float(clip.get("blend", base["blend"])), 0.001))
	var tb: Dictionary = tgt["bones"]
	for b in tb:
		cur[b] = (cur.get(b, Vector3.ZERO) as Vector3).lerp(tb[b], k)
	for b in cur:
		if not tb.has(b):
			cur[b] = (cur[b] as Vector3).lerp(Vector3.ZERO, k)
	cur_pos = cur_pos.lerp(tgt["pos"], k)
	_apply()


## Целевая поза клипа в момент t: base + клип (клип перекрывает кость целиком).
func _target(s: String, t: float) -> Dictionary:
	var clip: Dictionary = clips[s]
	var period := float(clip.get("period", base["period"]))
	var bones := {}
	for src in [base["bones"], clip.get("bones", {})]:
		for b in src:
			bones[b] = _chan(src[b], t, period) * 1.0
	var pos := Vector3.ZERO
	if clip.has("pos"):
		pos = _chan(clip["pos"], t, period, false)
	return {"bones": bones, "pos": pos}


func _chan(c: Dictionary, t: float, period: float, deg := true) -> Vector3:
	var bias := _v3(c.get("bias", [0, 0, 0]))
	var amp := _v3(c.get("amp", [0, 0, 0]))
	var w := sin(TAU * (float(c.get("freq", 1.0)) * t / period + float(c.get("phase", 0.0))))
	match str(c.get("wave", "sin")):
		"rect": w = maxf(w, 0.0)
		"abs": w = absf(w)
	var v := bias + amp * w
	return v * deg_to_rad(1.0) if deg else v


func _v3(a: Array) -> Vector3:
	return Vector3(float(a[0]), float(a[1]), float(a[2]))


## Поворот в пространстве модели: сначала Z, затем Y, затем X (вокруг сустава).
func _rot(e: Vector3) -> Basis:
	return Basis(Vector3.RIGHT, e.x) * Basis(Vector3.UP, e.y) * Basis(Vector3.BACK, e.z)


## Поворот каждой кости задан в пространстве модели и несёт за собой потомков:
## глобальный = R * глобальный_родителя * rest_локальный, откуда локальный = P⁻¹·R·P·rest.
func _apply() -> void:
	for i in names.size():
		var par := skel.get_bone_parent(i)
		var rest := skel.get_bone_rest(i)
		var p: Basis = cur_g[par] if par >= 0 else Basis.IDENTITY
		var r := _rot(cur.get(names[i], Vector3.ZERO))
		var local_b := p.inverse() * r * p * rest.basis
		skel.set_bone_pose_rotation(i, local_b.get_rotation_quaternion())
		cur_g[i] = p * local_b
	skel.set_bone_pose_position(0, skel.get_bone_rest(0).origin + cur_pos)

