func test_jump_height_and_duration() -> void:
	var s := _sim()
	s.step({"jump": true})
	var peak := 0.0
	var ticks := 1
	while s.state.player["z"] > 0.0 and ticks < 200:
		peak = maxf(peak, float(s.state.player["z"]))
		s.step({})
		ticks += 1
	assert_almost_eq(peak, float(s.bal["jump"]["height"]), 0.05, "высота")
